// 화면 리사이징

scwin.vBzProcsNo = "";
scwin.vReadMode = "Y";
scwin.vScrenID = "ULDSTF60002.xml";
scwin.fn_GetPar;
scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setCode = function() {
    //var usrCBData ="전체^(null),일반^1,벤처^2,기술정상^3,대형^4,스팩^5,스팩합병^6,분할재상장^7,외국기업^8"; 
    //cmb_INVSTG_CD.CBData =  usrCBData; 

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_BILL_STRT_DD, $c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    $c.stf.setObjectValue(edt_BILL_END_DD, $c.ut.cGetToday("yyyymmdd")); // 현재날짜
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp1);
    $c.stf.setObjectValue(edt_COMITE_STRT_DD, $c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    $c.stf.setObjectValue(edt_COMITE_END_DD, $c.ut.cGetToday("yyyymmdd")); // 현재날짜
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp2);
};
scwin.fn_setBzProcsNo = function(obj) {
    scwin.vBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
};
scwin.fn_getBzProcsNo = function() {
    return scwin.vBzProcsNo;
};
scwin.fn_list_sync = function() {
    var V_INVSTG_CD = " ";
    var V_ISSUE = " ";
    var V_RSN = " ";
    var V_RSLT = " ";
    var previousChecked = false;
    V_INVSTG_CD = "AND ( ";
    if (chk_INVSTG_CD2.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR GEN_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += "GEN_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD3.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR VENT_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += "VENT_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD4.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR SKIL_GRWTH_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += "SKIL_GRWTH_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD5.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR BIG_CORP_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += "BIG_CORP_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD6.checked) {
        // 우회상장심사
        if (previousChecked) {
            V_INVSTG_CD += " OR BACKLIST_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += "BACKLIST_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD7.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR SPEC_MERGE_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += " SPEC_MERGE_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD8.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR SPLIT_RELIST_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += " SPLIT_RELIST_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (chk_INVSTG_CD9.checked) {
        if (previousChecked) {
            V_INVSTG_CD += "OR FORN_COM_INVSTG_YN  = '1'  ";
        } else {
            V_INVSTG_CD += " FORN_COM_INVSTG_YN  = '1'  ";
        }
        previousChecked = true;
    }
    if (previousChecked) {
        V_INVSTG_CD += ") ";
    } else {
        V_INVSTG_CD = "";
    }
    previousChecked = false;
    V_RSLT = " AND COMITE_INVSTG_RSLT_CD IN ( ";
    if (chk_COMITE_RSLT1.checked) {
        V_RSLT += " '1' ";
        previousChecked = true;
    }
    if (chk_COMITE_RSLT2.checked) {
        if (previousChecked) {
            V_RSLT += ", '2' ";
        } else {
            V_RSLT += " '2' ";
        }
        previousChecked = true;
    }
    if (chk_COMITE_RSLT3.checked) {
        if (previousChecked) {
            V_RSLT += ", '3' ";
        } else {
            V_RSLT += " '3' ";
        }
        previousChecked = true;
    }
    if (chk_COMITE_RSLT4.checked) {
        if (previousChecked) {
            V_RSLT += ", '4' ";
        } else {
            V_RSLT += " '4' ";
        }
        previousChecked = true;
    }
    if (previousChecked) {
        V_RSLT += " ) ";
    } else {
        V_RSLT = "";
    }
    var fileContents = $c.ut.trim($c.stf.getObjectValue(txb_FileContent));
    if (fileContents.length > 0) {
        $c.stf.showObj(mgrd_Grid, true);
        $c.stf.showObj(grd_Grid, false);
    } else {
        $c.stf.showObj(mgrd_Grid, false);
        $c.stf.showObj(grd_Grid, true);
    }
    var stdIndCd = $c.stf.getObjectValue(txb_STD_IND_CD) == '' ? "A" : $c.stf.getObjectValue(txb_STD_IND_CD);
    var url = "/ComiteDelib.do?method=searchPrelistComitDelibRslt&outputMessageId=COMITERSLT_INOUT&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SCREN_ID=" + scwin.vScrenID + "&queryId=lds.stf.lstinvstg.prelminvstg.comitedelib.select.list.comite" + "&{P}COM_NM=" + $c.stf.getObjectValue(tbx_COM_NM) + "&{P}MAJ_PROD_NM=" + $c.stf.getObjectValue(tbx_MAJ_PROD_NM) + "&{P}COMITE_STRT_DD=" + $c.stf.getObjectValue(edt_COMITE_STRT_DD) + "&{P}COMITE_END_DD=" + $c.stf.getObjectValue(edt_COMITE_END_DD) + "&{P}BILL_STRT_DD=" + $c.stf.getObjectValue(edt_BILL_STRT_DD) + "&{P}BILL_END_DD=" + $c.stf.getObjectValue(edt_BILL_END_DD) + "&{P}STD_IND_CD=" + stdIndCd + "&{P}EMP_NM=" + $c.stf.getObjectValue(tbx_EMP_NM) + "&{P}V_RSLT=" + V_RSLT + "&{P}V_INVSTG_CD=" + V_INVSTG_CD + "&{P}V_ISUE_CONTN=" + $c.stf.getObjectValue(tbx_isue_contn_search) + "&{P}V_NAPPROV_RSN=" + $c.stf.getObjectValue(tbx_napprov_rsn_search) + "&{P}V_RSN=" + V_RSN + "&{P}V_FILE_CONTENT=" + fileContents;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_Grid);
};


/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, "리스트", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.fn_GetParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_STD_IND_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_STD_IND_NM); // 명칭값을 포함할 컨트롤

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParStdInd = function(arrPar) {
    txb_STD_IND_CD.setValue(arrPar[0].STD_IND_CD);
    txb_STD_IND_NM.setValue(arrPar[0].IND_NM);
};
scwin.fn_GetParIssue = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = dts_Issue;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/*	function fn_SetParIssue(arrPar) {
		tbx_revw.value = arrPar[0].REVIEW;
		tbx_approv.value = arrPar[0].APPROV;
		tbx_search.value = arrPar[0].SEARCH_TEXT;
	    CopyDataSet(arrPar[0].DTS_ISSUE, dts_Issue);
	   dts_Issue.ResetStatus();
	}*/
scwin.fn_SetParIssue = function(arrPar) {
    tbx_isue_contn.setValue(arrPar[0].ISUE);
    tbx_napprov_rsn.setValue(arrPar[0].NAPPROV);
    tbx_isue_contn_search.setValue(arrPar[0].ISUE_SEARCH_TEXT);
    tbx_napprov_rsn_search.setValue(arrPar[0].NAPPROV_SEARCH_TEXT);
    $c.stf.CopyDataSet(arrPar[0].DTS_ISSUE, dts_Issue);
    //dts_Issue.ResetStatus();

};
scwin.fn_setIssue = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=DELIB_ISSUE_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.prelistingkosdaq.select.cmtdelib.issue.comite" + "&{P}PARAM01=" + '' + "&{P}PARAM02=" + '';
    dts_Issue.DataID = encodeURI(url);
    dts_Issue.Reset();
};
frame.SetEvent("onwinstat", OnWinStat);
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gOldWidthSize = frame.width;
scwin.gNewWidthSize = 0;
scwin.OnSized = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    //gNewHeightSize = frame.height;
    scwin.GauceObjResize(frame.width, frame.height);
};
scwin.OnSizedMax = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    //alert(frame.width);
    scwin.GauceObjResize($c.frame.path("/").width - 10, frame.height);
};
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg == "activate" && winID.substring(0, 6) == "Child_") {
        //frameMain의 함수 호출
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg == "maximize") {
        scwin.maxval = 1;
    } else if (statmsg == "size") {
        if (scwin.maxval == 0) {
            var strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval == 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};
scwin.GauceObjResize = function(a, b) {
    var gw;
    var ew;

    // GRID 처리
    grd_Grid.ReDraw = "false";
    gw = grd_Grid.getStyle("width");
    ew = a - parseInt(gw) - 35;
    grd_Grid.setGridWidth(parseInt(gw) + ew);
    grd_Grid.ReDraw = "true";
    scwin.gOldWidthSize = frame.width;
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_BILL_STRT_DD, edt_BILL_END_DD) && $c.stf.compareFromToDate2(edt_COMITE_STRT_DD, edt_COMITE_END_DD)) {
        scwin.fn_list_sync();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.btn_COMITE_SDate_onclick = function() {
    popUpCalendar2(edt_COMITE_STRT_DD);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_COMITE_END_DD);
};
scwin.btn_BILL_SDate_onclick = function() {
    popUpCalendar2(edt_BILL_STRT_DD);
};
scwin.btn_END_SDate_onclick = function() {
    popUpCalendar2(edt_BILL_END_DD);
};
scwin.gform_onload = function() {
    $c.stf.showObj(tbx_search, false);
    $c.stf.showObj(tbx_isue_contn_search, false);
    $c.stf.showObj(tbx_napprov_rsn_search, false);
    scwin.fn_setCode();
    //	fn_initSearchDate(tbx_COMITE_STRT_DD, tbx_COMITE_END_DD);
    //	fn_initSearchDate(tbx_BILL_STRT_DD, tbx_BILL_END_DD);

    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
    scwin.fn_setIssue();
};
scwin.img_ind_onclick = function() {
    scwin.fn_GetPar = fn_GetParStdInd;
    scwin.fn_SetPar = fn_SetParStdInd;
    $c.lc.fn_PopFindStdIndCd();
};
scwin.img_issue_onclick = async function() {
    scwin.fn_GetPar = fn_GetParIssue;
    scwin.fn_SetPar = fn_SetParIssue;
    await $c.frame.CreateDialogFrame("DLG_ISSUE", "../lstmgt/ULDSTF60005.gfm", "주요이슈 및 미승인ㆍ철회사유선택", 10, 10, 830, 900, "window");
};
scwin.img_approv_onclick = async function() {
    scwin.fn_GetPar = fn_GetParIssue;
    scwin.fn_SetPar = fn_SetParIssue;
    await $c.frame.CreateDialogFrame("DLG_ISSUE", "../lstmgt/ULDSTF60005.gfm", "주요이슈 및 미승인ㆍ철회사유선택", 10, 10, 830, 900, "window");
};
scwin.cmb_PeriodTp1_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp1, "VALUE", cmb_PeriodTp1.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_BILL_STRT_DD, edt_BILL_END_DD);
};
scwin.cmb_PeriodTp2_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp2, "VALUE", cmb_PeriodTp2.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_COMITE_STRT_DD, edt_COMITE_END_DD);
};
scwin.chk_INVSTG_CD1_onclick = function() {
    if (chk_INVSTG_CD1.checked) {
        chk_INVSTG_CD2.setValue(1);
        chk_INVSTG_CD3.setValue(1);
        chk_INVSTG_CD4.setValue(1);
        chk_INVSTG_CD5.setValue(1);
        chk_INVSTG_CD6.setValue(1);
        chk_INVSTG_CD7.setValue(1);
        chk_INVSTG_CD8.setValue(1);
        chk_INVSTG_CD9.setValue(1);
    }
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    if ("ATTACH_FILE_NM" == colid && dts_List.getCellData(row, "ATTACH_FILE_NM") != "") {
        //사전협의보고서
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + dts_List.getCellData(row, "BZ_PROCS_NO") + "&attach_seq=1&gubun=37";
    }
    if ("FILE_NM1" == colid && dts_List.getCellData(row, "FILE_NM1") != "") {
        //안건파일 
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + dts_List.getCellData(row, "BZ_PROCS_NO") + "&comite_dd=" + dts_List.getCellData(row, "COMITE_DD") + "&attach_seq=2&gubun=38";
    }
    if (("ISSUE" == colid && dts_List.getCellData(row, "ISSUE") != "") || ("RSN" == colid && dts_List.getCellData(row, "RSN") != "")) {
        // 주요 이슈사항,  미승인ㆍ철회사유
        await $c.frame.CreateDialogFrame("DLG_ISSUE_DTL", "/lstmgt/ULDSTF60001.gfm", "주요이슈사항", 10, 10, 820, 900, "window");
    }
};
scwin.txb_FileContent_onkeydown = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
scwin.mgrd_Grid_OnLButtonDblClk = async function(type, row, colid, x, y) {
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    if ("ATTACH_FILE_NM" == colid && dts_List.getCellData(row, "ATTACH_FILE_NM") != "") {
        //사전협의보고서
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + dts_List.getCellData(row, "BZ_PROCS_NO") + "&attach_seq=1&gubun=37";
    }
    if ("FILE_NM1" == colid && dts_List.getCellData(row, "FILE_NM1") != "") {
        //안건파일 
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&bz_procs_no=" + dts_List.getCellData(row, "BZ_PROCS_NO") + "&comite_dd=" + dts_List.getCellData(row, "COMITE_DD") + "&attach_seq=2&gubun=38";
    }
    if (("ISSUE" == colid && dts_List.getCellData(row, "ISSUE") != "") || ("RSN" == colid && dts_List.getCellData(row, "RSN") != "")) {
        // 주요 이슈사항,  미승인ㆍ철회사유
        await $c.frame.CreateDialogFrame("DLG_ISSUE_DTL", "/lstmgt/ULDSTF60001.gfm", "주요이슈사항", 10, 10, 820, 900, "window");
    }
};
